public int minDistance(String word1, String word2) {
    int m = word1.length(), n = word2.length();
    Integer[][] memo = new Integer[m + 1][n + 1];
    return solve(word1, word2, m, n, memo);
}

private int solve(String w1, String w2, int i, int j, Integer[][] memo) {
    if (i == 0) {
        return j;
    }
    if (j == 0) {
        return i;
    }
    if (memo[i][j] != null) {
        return memo[i][j];
    }
    int result;
    if (w1.charAt(i - 1) == w2.charAt(j - 1)) {
        result = solve(w1, w2, i - 1, j - 1, memo);
    } else {
        int delete = solve(w1, w2, i - 1, j, memo);
        int insert = solve(w1, w2, i, j - 1, memo);
        int replace = solve(w1, w2, i - 1, j - 1, memo);
        result = 1 + Math.min(delete, Math.min(insert, replace));
    }
    memo[i][j] = result;
    return result;
}

